  function parts(path){if(typeof path!=='string'||!(path==='/'+ROOT||path.startsWith('/'+ROOT+'/')))throw new Error('更新只能写入万法宗扩展自己的字段。');const a=path.slice(1).split('/').map(v=>v.replace(/~1/g,'/').replace(/~0/g,'~'));if(a.some(v=>!v||danger.has(v)||v.startsWith('_')))throw new Error('更新不能改写脚本凭据或使用无效字段。');return a;}
