function createWanfaView(C,assets){
  'use strict';
  const E=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const br=v=>E(v).replace(/\n/g,'<br>'),icon=n=>assets.toolIcons?.[n]||'<svg viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round">'+(assets.icons[n]||assets.icons.scroll)+'</svg>';
  const button=(label,action,props={},primary=false,disabled=false)=>'<button type="button" class="btn'+(primary?'':' secondary')+'" data-action="'+action+'" '+Object.entries(props).map(([k,v])=>'data-'+k+'="'+E(v)+'"').join(' ')+' '+(disabled?'disabled':'')+'>'+E(label)+'</button>';
  const link=(label,action,props={})=>'<button type="button" class="quiet-link" data-action="'+action+'" '+Object.entries(props).map(([k,v])=>'data-'+k+'="'+E(v)+'"').join(' ')+'>'+E(label)+icon('arrow')+'</button>';
  const empty=(text,ask='')=>'<section class="panel wf-empty"><p>'+E(text)+'</p>'+(ask?button('问询安排','ask',{text:ask}):'')+'</section>';
  const num=n=>C.count(n)?n.toLocaleString('en-US'):'待核对';
  const list=(s,k)=>C.collection(C.extension(s),k);
  const status=(label,kind='')=>'<span class="wf-status '+kind+'">'+E(label||'待核对')+'</span>';
  function value(v,depth=0){
    if(v===undefined||v===null||v==='')return '待核对';if(typeof v==='boolean')return v?'是':'否';
    if(typeof v!=='object')return br(v);
    if(depth>=5)return '记录层级较多，请核对具体事项。';
    if(Array.isArray(v))return v.length?'<ul class="wf-value-list">'+v.map(x=>'<li>'+value(x,depth+1)+'</li>').join('')+'</ul>':'暂无记录';
    const rows=Object.entries(v).filter(([k])=>!k.startsWith('_'));return rows.length?'<dl class="wf-nested-facts">'+rows.map(([k,x])=>'<dt>'+E(k)+'</dt><dd>'+value(x,depth+1)+'</dd>').join('')+'</dl>':'暂无公开记录';
  }
  function facts(rows){return '<dl class="dialog-facts">'+rows.map(([a,b])=>'<dt>'+E(a)+'</dt><dd>'+value(b)+'</dd>').join('')+'</dl>';}
  const group=(title,rows)=>'<section class="dialog-section"><h3>'+E(title)+'</h3>'+facts(rows)+'</section>';
  const groupHTML=(title,body)=>'<section class="dialog-section"><h3>'+E(title)+'</h3>'+body+'</section>';
  function intro(kicker,title,subtitle=''){return '<div class="page-intro"><div><span class="eyebrow">'+E(kicker)+'</span><h2>'+E(title)+'</h2>'+(subtitle?'<p class="page-subtitle">'+E(subtitle)+'</p>':'')+'</div><div class="study-actions">'+link('门内大比','tournament')+link('修行岁序','calendar')+'</div></div>';}
  function section(title,name,right=''){return '<div class="section-title"><h3>'+icon(name)+E(title)+'</h3>'+right+'</div>';}
  function formation(){return '<svg class="study-drawing" viewBox="0 0 200 200" aria-hidden="true"><circle cx="100" cy="100" r="79"/><circle cx="100" cy="100" r="63" stroke-dasharray="2 5"/><circle cx="100" cy="100" r="47"/><path d="M100 9v181M9 100h181M36 36l128 128M36 164 164 36M100 21l69 119H31ZM100 179 31 60h138Z"/><circle cx="100" cy="100" r="19"/></svg>';}
  function cityCard(){return '<button type="button" class="city-card" data-action="city-image"><img src="'+assets.image+'" alt="万法天仪仙城概念全景"><span class="city-copy"><span><small>云外有城 · 万法同归</small><strong>万法天仪 · 仙城全景</strong></span>'+icon('arrow')+'</span></button>';}
  function reward(t){const g=C.str(t.等级).replace(/级任务|级/g,'');return ['地','天'].includes(g)?t.奖励说明||'奖励安排待核对':C.count(t.奖励贡献)?num(t.奖励贡献)+' 贡献'+(t.奖励说明?' · '+t.奖励说明:''):'报酬待核对';}
  function studyCard(s){const first=list(s,'研习').find(([,r])=>!['已完成','已归档'].includes(r.状态));if(!first)return empty('案头尚无已登记的研习。先核对正在练习的功法、阵图或师承课题。','请根据我实际已有的功法、当前修行和已确认师承，整理一项正在推进的研习，未知则先问询，不凭空授予功法或增加熟练度。');const [id,r]=first;return '<article class="wf-study-content">'+'<div class="study-kind">'+E((r.方向||'个人研习')+' · '+(r.阶段||r.状态||'依实际进度'))+'</div><h4>'+E(r.名称||id)+'</h4><p>'+br(r.进展||r.说明||'研习进度尚待核对。')+'</p><div class="study-actions">'+link('展开研习','record',{collection:'研习',id})+'</div></article>';}
  function home(s){const p=C.obj(s.主角),x=C.extension(s),n=C.obj(x.名籍),r=C.role(s),tasks=C.elder(s)?list(s,'职事').filter(([,t])=>!['已完成','已归档'].includes(t.状态)):list(s,'任务').filter(([,t])=>['进行中','待结算'].includes(t.状态)),agenda=C.agenda(s).filter(e=>e.来源!=='任务'),rows=[];
    for(const [id,t]of tasks.slice(0,2))rows.push('<article class="task-row"><span class="task-glyph">'+(C.elder(s)?'议':'任')+'</span><div><h4>'+E(t.名称||id)+'</h4><p>'+E(C.elder(s)?t.状态||'依实际安排':reward(t))+'</p></div>'+link('查看','record',{collection:C.elder(s)?'职事':'任务',id})+'</article>');
    for(const a of agenda.slice(0,Math.max(0,3-rows.length)))rows.push('<article class="task-row"><span class="task-glyph date">'+E(a.来源.slice(0,1))+'</span><div><h4>'+E(a.标题)+'</h4><p>'+E(a.时间||'待排期')+'</p></div>'+link('查看','agenda',{id:a.id})+'</article>');
    const pending=list(s,'办理').find(([,r])=>['待确认','已批准','待核价'].includes(r.状态));if(pending){const [id,r]=pending;rows.push('<article class="task-row" data-wf-key="近期办理-'+E(id)+'"><span class="task-glyph">办</span><div><h4>'+E(r._凭证?.名称||id)+'</h4><p>'+E(receiptDescription(r))+'</p></div>'+link('查看','record',{collection:'办理',id})+'</article>');}
    const news=list(s,'闻讯').slice(0,3);return intro('万法机关令 / 我的修行','此身有归处，此道有来日')+'<section class="id-card"><div class="personal-token" aria-hidden="true"><span class="token-name">万法</span></div><div class="id-info"><h3>'+E(p.姓名||'名籍待核对')+'<span class="inline-tag">'+E(r||'身份待核对')+'</span></h3><p class="id-subtitle">'+E(p.境界||'境界待核对')+'</p><dl class="id-facts"><div><dt>师承</dt><dd>'+E(n.师承||'待核对')+'</dd></div><div><dt>居所</dt><dd>'+E(n.居所||'待安排')+'</dd></div></dl></div><div class="credit"><span class="credit-label">宗门贡献</span><strong>'+num(p.宗门贡献)+'</strong><small>'+E(C.saint(s)?'圣位月俸十万 · 依实际周期':C.special(s)?'指定丹药按规审批配给':C.elder(s)?'宗门高阶职责 · 依规调拨':'以功换法 · 百艺入道')+'</small>'+link('名籍与权限','profile')+'</div></section><div class="home-grid"><div>'+section(C.elder(s)?'传道与研习':'此刻修行','book','<small>案头一事，慢慢研磨</small>')+'<section class="study-card wf-current-study">'+studyCard(s)+practice(s)+'</section>'+'<section class="task-section">'+section('近期事务','scroll',link('全部事务','page',{page:'merit'}))+(rows.length?'<div class="task-list">'+rows.join('')+'</div>':empty('此刻尚无已登记的在办事务。','请按当前身份、境界和实际地点核对近期事务。明镜阁长老只安排高阶职责，不接取任务。'))+'</section></div><aside class="right-rail"><div>'+section('同门近况','lamp','<small>已知消息 · 注明来处</small>')+(news.length?'<div class="news-box">'+news.map(([id,v])=>'<article class="news-item"><div class="news-meta"><span class="news-type">'+E(v.类别||'仙城近况')+'</span><span>'+E(v.来源||'来源待核对')+'</span></div><h4>'+E(v.标题||id)+'</h4><p>'+br(v.摘要||v.说明)+'</p>'+link('了解此事','record',{collection:'闻讯',id})+'</article>').join('')+'</div>':empty('尚无新近告示或同门消息。','请按我实际可知的信息补充少量万法宗近日消息，注明来源、时间与传闻性质，不推进日期或直接触发重大事件。'))+'</div><div>'+cityCard()+'<p class="city-note">点开远眺仙城，不打断眼前修行。</p></div></aside></div><div class="bottom-note">'+icon('spark')+'<span>有教无类，百艺皆可入道。</span><span>'+E(s.世界?.当前地点||'当前地点待核对')+'</span></div>';}
  function teaching(s){return intro('传道大殿 / 修学与问难','有所学，亦有所问','讲席按真实会期安排，听讲与习得分别记录。')+list(s,'课业').map(([id,c])=>'<article class="panel course-row"><div class="course-date">'+E(c.时辰||'待排期')+'<small>'+E(c.日期||c.开始||'日期待确认')+'</small></div><div><div class="small-label">'+E(c.地点||'讲席待核对')+'</div><h3>'+E(c.名称||id)+'</h3><p>'+br(c.说明)+'</p><div class="panel-meta">'+E(c.条件||'按身份与实际修为核对')+'</div></div>'+button('问询赴课','ask',{text:'我想参加「'+(c.名称||id)+'」，先核对身份、日期、地点、席位与费用，再安排赴课；查看不增加修为或熟练度。'})+'</article>').join('')+(list(s,'课业').length?'':empty('近期课业尚待核对，不自动套用固定课程。','请根据我的实际身份与境界核对可参加的基础讲席、师承答疑或长老开坛；日期未知则保留待排期。'))+'<div class="two-col"><section class="panel"><div class="small-label">个人研习</div><h3>把疑问留在案上</h3><p>记录已经遇到的问题，带着推演与批注去请教。</p>'+button('核对研习','ask',{text:'请核对我当前实际研习及其进度，只补写已有变化，不新增未经获得的功法。'})+'</section><section class="panel"><div class="small-label">后天入道</div><h3>器灵根与丹灵根</h3><p>查看已经确认的施术记录，或问询适配条件、风险与契约。</p>'+button('查看入道记录','roots')+'</section></div>';}
  function offerType(s,o){const p=C.pillPolicy(s,o.名称);return p?(p.战略?'战略申领':p.免费?'配给':'兑换'):o.方式;}
  function offerCost(s,o){const p=C.pillPolicy(s,o.名称);if(p)return p.免费?(p.战略?'审批配给 · 须双重审批':'明镜阁审批 · 免费配给'):p.战略?'战略审批 · 不列常规价格':num(p.价)+' 贡献';return C.count(o.单价)?num(o.单价)+' 贡献'+(o.计费单位==='日'?'/日':''):'报价待核对';}
  function bookRows(s,ui){return list(s,'目录').filter(([,o])=>['借阅','拓印','传承'].includes(o.方式)&&(o.名称+' '+o.分类+' '+o.描述).includes(ui.search||'')).map(([id,o])=>'<article class="panel book-card"><div class="book-spine" aria-hidden="true">'+E(C.str(o.名称,6))+'</div><div><div class="small-label">'+E(o.品阶||o.分类||'典籍')+(o.层数?' · 第'+E(o.层数)+'层':'')+'</div><h3>'+E(o.名称||id)+'</h3><p>'+br(o.描述)+'</p><div class="panel-meta">'+E(offerCost(s,o))+'</div>'+button(C.permitted(s,o)?'查看与申请':'查看条件','offer',{id})+'</div></article>').join('')||empty('这份已确认目录中暂无对应典籍。','我想向藏经阁问询适合当前境界和阅览权限的典籍、阵图或机关图谱。请只整理少量实际可提供的目录，费用未确认则不填单价。');}
  function library(s,ui){return intro('万法藏经阁 / 检索与借阅','万卷在阁，择一而深研','当前最高阅览层级：'+C.bookFloor(s)+'层。权限不表示已经学会或能施展。')+'<label class="search-bar">'+icon('search')+'<input data-field="search" value="'+E(ui.search||'')+'" placeholder="寻一卷典籍、阵图或机关图谱" aria-label="检索典籍"></label><div class="catalog" id="wf-book-results">'+bookRows(s,ui)+'</div><section class="panel"><div class="small-label">我的借阅</div>'+list(s,'借阅').filter(([,b])=>b.状态==='借阅中').map(([id,b])=>'<div class="wf-line"><div><strong>'+E(b.名称)+'</strong><p>'+E(b.应还时间||'应还时间待核对')+'</p></div>'+button('申请归还','apply',{type:'归还',id})+'</div>').join('')+(list(s,'借阅').some(([,b])=>b.状态==='借阅中')?'':'<p>尚无正在借阅的典籍。</p>')+'</section>';}
  function workshop(s){return intro('百工研造 / 工坊与课题','一器一阵，皆有可研之处','阶段、用料与协作依据实际研造记录，不因打开界面自动生产。')+'<div class="two-col">'+list(s,'研造').map(([id,p])=>'<article class="panel"><div class="small-label">'+E(p.方向||'研造课题')+' · '+E(p.阶段||p.状态||'待核对')+'</div><h3>'+E(p.名称||id)+'</h3><p>'+br(p.进展||p.说明)+'</p>'+button('查看案卷','record',{collection:'研造',id})+'</article>').join('')+'</div>'+(list(s,'研造').length?'':empty('尚无已登记的研造项目。','请按我已知的技艺、图谱、材料与实际场地，核对可以推进的一项机关、丹器或阵法课题，不凭空发放材料或造物。'))+section('工坊与场地','work')+list(s,'工坊').map(([id,f])=>'<section class="panel"><div class="small-label">'+E(f.地点||f.方向||'场地待核对')+'</div><h3>'+E(f.名称||id)+'</h3><p>'+br(f.说明)+'</p><div class="panel-meta">'+E(C.workshopPrice(s,f).有效?C.workshopPrice(s,f).说明+' · 本月场租 '+num(C.workshopPrice(s,f).总价)+' 贡献':C.workshopPrice(s,f).说明)+'</div>'+(f.我的租借?'<p>租借：'+E(f.我的租借.开始)+' — '+E(f.我的租借.结束)+'</p>':'')+button('问询租借','workshop',{id})+'</section>').join('')+(list(s,'工坊').length?'':empty('工坊排期与报价尚未确认。','我想问询符合当前身份与修为的工坊，先核对设备、可用日期、免租配额与实际报价。'));}
  function pillTable(s){return '<section class="panel"><div class="small-label">核心破境资源申领与配额</div><h3>丹药有定价，申领有章程</h3><table class="ledger"><thead><tr><th>丹药</th><th>常规申领</th><th>费用／审批</th></tr></thead><tbody>'+Object.entries(C.pills).map(([name,p])=>'<tr><td>'+E(name)+'</td><td>'+E(p.战略?'宗门战略物资':p.阶===1?'外门':p.阶===2?'内门':'真传')+'</td><td>'+E(offerCost(s,{名称:name}))+'</td></tr>').join('')+'</tbody></table><p>圣位与长老亲传的指定六种丹药按明镜阁审批免费配给；天罡合体丹仍须宗主与明镜阁长老审批。虚灵丹不适用这项免费待遇。固定规则不代表已经备货。</p>'+button('问询资源目录','ask',{text:'我想向任务功德堂核对当前可申领的破境资源和实际库存，请遵循固定价格、身份及审批规则，未确认库存不要编造已到货。'})+'</section>';}
  function tasks(s,ui){if(C.elder(s))return list(s,'职事').map(([id,t])=>'<article class="panel"><div class="small-label">明镜职事 · '+E(t.状态||'待核对')+'</div><h3>'+E(t.名称||id)+'</h3><p>'+br(t.说明||t.目标)+'</p>'+button('查看案卷','record',{collection:'职事',id})+'</article>').join('')||empty('尚无已登记的审批、传道或议事事务。明镜阁长老不接取各级任务。','请按我的实际长老职责核对宗门议事、资源审批或传道安排，不给我发布可接取的弟子任务。');
    const filters=['进行中','待接取','归档'],selected=filters.includes(ui.tasks)?ui.tasks:'进行中';return '<div class="tabs">'+filters.map(v=>'<button class="chip '+(selected===v?'active':'')+'" data-action="task-filter" data-value="'+v+'">'+v+'</button>').join('')+'</div>'+list(s,'任务').filter(([,t])=>selected==='进行中'?['进行中','待结算'].includes(t.状态):selected==='待接取'?['待接取','待确认接取'].includes(t.状态):['已完成','失败','放弃','失效'].includes(t.状态)).map(([id,t])=>'<article class="panel wf-record" data-collection="任务" data-record-id="'+E(id)+'" data-wf-key="任务-'+E(id)+'"><div class="small-label">'+E((t.等级||'等级待核对')+' · '+t.状态)+'</div><h3>'+E(t.名称||id)+'</h3><p>'+br(t.目标||t.说明)+'</p><div class="reward">'+E(reward(t))+'</div><div class="panel-meta"><span>'+E(t.地点||'地点待核对')+'</span><span>'+E(t.截止时间||t.时限||'期限依确认安排')+'</span></div><div class="study-actions">'+(t.状态==='待确认接取'?button('撤回接取申请','cancel-accept',{id}):t.状态==='待接取'?button(C.taskAllowed(s,t)?'接取任务':'资格待核对','accept',{id},true,!C.taskAllowed(s,t)):button('查看进展','record',{collection:'任务',id}))+(['进行中','待结算'].includes(t.状态)?link('拟写回报','ask',{text:'我想回报「'+(t.名称||id)+'」的实际进展，核对完成依据与交接；没有完成的部分保持原状态，不提前领取奖励。'}):'')+'</div></article>').join('')+button('问询适合的事务','ask',{text:'请根据我的正式身份、实际境界与地点提供少量可接事务，按任务功德堂分级与报酬，不覆盖进行中任务。地级、天级明确非贡献奖励，任务强度须适配实际能力。'});}
  function receiptStatus(r){return r.状态==='已完成'?'已办妥':r.状态==='已批准'?'已批准 · 待结算':r.状态||'待核对';}
  function receiptDescription(r){const p=C.obj(r._凭证);return r.状态==='已完成'?(p.类型==='工坊租借'?'租期与费用已登记；开工、材料与产出依实际剧情。':'费用与实际结果已按凭据一次登记。'):r.状态==='已批准'?'已取得批准，仍需核对实际结果、交付与结算；不据此推定已经持有。':r.状态==='已撤销'?'申请已撤销，已有实际结果不由此回退。':'尚未实际办理，不扣贡献、不授予物品或习得。';}
  function receipts(s){return list(s,'办理').map(([id,r])=>'<section class="panel wf-record" data-collection="办理" data-record-id="'+E(id)+'" data-wf-key="办理-'+E(id)+'"><div class="wf-receipt-head"><h3>'+E(r._凭证?.名称||id)+'</h3>'+status(receiptStatus(r),r.状态==='已完成'?'success':r.状态==='待确认'?'pending':'')+'</div><p>'+E(receiptDescription(r))+'</p><div class="panel-meta">'+E('申请时间：'+(r.申请时间||'待核对'))+'</div>'+(r.说明?'<p>'+br(r.说明)+'</p>':'')+'<div class="wf-flow"><span class="reached">登记申请</span><span>→</span><span class="'+(['已批准','已完成'].includes(r.状态)?'reached':'')+'">核验与审批</span><span>→</span><span class="'+(r.状态==='已完成'?'reached':'')+'">实际结果与结算</span></div><div class="study-actions">'+link('查看办理详情','record',{collection:'办理',id})+((r._凭证?.待核价&&r.状态==='已批准'&&C.count(r.结果?.核定费用)&&r.结果.核定费用>0&&!r._核价确认)?button('确认核定费用 '+num(r.结果.核定费用),'price',{id}):'')+(['待确认','已批准'].includes(r.状态)?button('撤销申请','cancel',{id}):'')+'</div></section>').join('')||empty('暂无界面办理记录。自然剧情收获仍由原卡记录。');}
  function merit(s,ui){const choices=[C.elder(s)?'明镜职事':'任务','资源规则','物资目录','办理记录'];const chosen=choices.includes(ui.merit)?ui.merit:choices[0];let content=chosen===choices[0]?tasks(s,ui):chosen==='资源规则'?pillTable(s):chosen==='办理记录'?receipts(s):list(s,'目录').filter(([,o])=>!['借阅','拓印','传承'].includes(o.方式)).map(([id,o])=>'<article class="panel"><div class="small-label">'+E(o.分类||'物资')+'</div><h3>'+E(o.名称||id)+'</h3><p>'+br(o.描述)+'</p><div class="reward">'+E(offerCost(s,o))+'</div>'+button('查看申领条件','offer',{id})+'</article>').join('')||empty('实际物资目录尚待核对。','我想问询任务功德堂当前实际可提供的物资、价格及库存，按既定申领规则补充少量目录。');return intro(C.elder(s)?'明镜职事 / 审议与资源':'任务功德堂 / 宗门往来',C.elder(s)?'议宗门事，守万法之序':'有所托付，亦有所获',C.elder(s)?'长老承担高阶职责，不进入任务接取体系。':'申请、批准与实际兑现分别记录。')+'<div class="tabs">'+choices.map(v=>'<button class="chip '+(v===chosen?'active':'')+'" data-action="merit-filter" data-value="'+v+'">'+v+'</button>').join('')+'</div>'+content;}
  function city(s){return intro('万法天仪 / 城中日常','云上有城，城中有同门','导览不改变实际地点，前往仍由剧情承接。')+cityCard()+'<div class="districts wf-districts">'+[['外城 · 玄机坊','天仪下坊公开接引码头','接引登记殿','玄机舍区','宗门坊市','灵膳坊与灵泉'],['内城 · 千机峰','传道大殿','任务功德堂','机关、丹器与阵法堂','万象试炼塔'],['核心 · 太虚云阙','万法藏经阁','明镜湖与明镜阁','太虚神枢殿','天斗研究院']].map(d=>'<section class="panel"><div class="small-label">仙城分区</div><h3>'+E(d[0])+'</h3><ul>'+d.slice(1).map(n=>'<li>'+link(n,'ask',{text:'我想了解「'+n+'」的公开情况与当前准入条件，请核对我的身份、地点与实际可知信息；查看不自动前往，不公开禁区机密。'})+'</li>').join('')+'</ul></section>').join('')+'</div>'+section('同门来往','lamp')+list(s,'闻讯').map(([id,n])=>'<article class="panel"><div class="small-label">'+E((n.来源||'来源待核对')+' · '+(n.性质||'性质待核对'))+'</div><h3>'+E(n.标题||id)+'</h3><p>'+br(n.摘要||n.说明)+'</p>'+button('继续问询','record',{collection:'闻讯',id})+'</article>').join('');}
  function calendar(s,ui){const m=C.monthRows(s,ui.month);if(!m)return '<p>世界时间尚未明确，暂不推算日历。</p>';return button('查看门内大比','tournament')+'<div class="wf-calendar-tools">'+button('上月','month',{step:-1})+'<strong>元会历 '+m.year+' 年 '+m.month+' 月</strong>'+button('下月','month',{step:1})+'</div><div class="wf-calendar-week">'+['一','二','三','四','五','六','日'].map(v=>'<span>'+v+'</span>').join('')+'</div><div class="wf-calendar">'+m.rows.map(d=>{return '<button class="wf-day '+(d.month!==m.month?'other ':'')+(d.today?'today':'')+'" data-action="calendar-day" data-value="'+d.ms+'"><b>'+d.day+'</b><small>'+E(d.events.map(e=>e.标题).slice(0,2).join(' · '))+'</small></button>';}).join('')+'</div><p class="dialog-note">仅按世界时间展示已登记日程与明确的固定会期。半年、季度等尚无首届日期的活动不编造排期。</p><div class="wf-calendar-list">'+C.agenda(s).slice(0,15).map(e=>'<div class="wf-line"><div><strong>'+E(e.标题)+'</strong><p>'+E(e.时间||'待排期')+'</p></div>'+link('查看','agenda',{id:e.id})+'</div>').join('')+'</div>'+button('拟写记事','note');}
  function profile(s){const p=C.obj(s.主角),n=C.obj(C.extension(s).名籍);return group('基本信息',[['姓名',p.姓名],['身份',p.宗门],['境界',p.境界],['灵根',p.灵根]])+group('师承与居所',[['师承',n.师承],['居所',n.居所],['入门时间',n.入门时间],['入门方式',n.入门方式]])+group('宗门权限',[['藏经范围','最高至第'+C.bookFloor(s)+'层'],['资源申领',C.special(s)?'指定六种丹药按明镜阁审批免费配给；天罡合体丹仍须双审，虚灵丹不套免费待遇。':'依身份、贡献、实际库存与审批办理。'],['权限边界','阅览资格不代表已习得，审批不代表已交付。'],['办理阶段',C.extension(s).入门?.阶段]])+'<div class="dialog-actions">'+button('核对名籍与晋升','ask',{text:'请核对我已经确认的万法宗身份、师承、居所和真实入门时间，只补齐缺失项。晋升依实际修为与宗门规则办理，不重复招生、发令、发月俸或提高境界。'})+'</div>';}
  function record(s,collection,id){const r=C.extension(s)[collection]?.[id];if(!r)return '<p>记录已变化，请重新查看。</p>';const rows=Object.entries(r).filter(([k])=>!k.startsWith('_')&&!['名称','标题','结果','说明','目标','进展','奖励记录'].includes(k));let body='';if(collection==='任务'||collection==='职事'){body=group('事项与进度',[['目标',r.目标||r.说明],['实际进展',r.进展||'依已有记录核对'],['状态',r.状态],['地点',r.地点],['期限',r.截止时间||r.时限]])+group('报酬与交接',[['约定奖励',collection==='任务'?reward(r):r.奖励说明||'依实际职事安排'],['完成依据',r.完成依据],['已兑现记录',r.奖励记录||'尚无已兑现记录']]);}else if(collection==='办理'){const p=C.obj(r._凭证);body=group('申请摘要',[['办理方式',p.类型],['状态',receiptStatus(r)],['数量',p.数量],['预计费用',p.待核价?'待审批核价':C.count(p.总价)?num(p.总价)+' 贡献':'待核对'],['申请时间',r.申请时间]])+group('审批与实际结果',[['当前说明',receiptDescription(r)],['结果',r.结果],['备注',r.说明]]);}else body=group('当前记录',rows)+group('进展与说明',[['说明',r.进展||r.说明||r.摘要],['实际结果',r.结果]]);return body+'<div class="dialog-actions">'+button('拟写后续行动','ask',{text:'我想继续处理「'+(r.名称||r.标题||id)+'」，请核对实际进度、身份、日期与地点，再安排后续，不提前结算或自动推进。'})+'</div>';}
  function offer(s,id,ui){const o=C.extension(s).目录?.[id];if(!o)return '<p>目录已变化。</p>';const allowed=C.permitted(s,o),type=offerType(s,o),qty=Number(ui.qty??1),days=Number(ui.days??1),qtyOK=Number.isInteger(qty)&&qty>=1&&qty<=99,daysOK=Number.isInteger(days)&&days>=1&&days<=366;let total='待核对报价',warning='';try{const p=C.request({stat_data:s},type,id,{rid:'预览-'+Date.now(),qty,days}).receipt._凭证;total=p.待核价?'待审批核价':p.总价===0?'免费配给／办理':num(p.总价)+' 贡献';}catch(error){warning=error.message;const policy=C.pillPolicy(s,o.名称),price=policy?.免费?0:policy?.价??o.单价;if(C.count(price)&&qtyOK&&daysOK)total=num(price*(type==='借阅'?(o.计费单位==='日'?days:1):qty))+' 贡献';}return '<p>'+br(o.描述)+'</p>'+group('提供与办理条件',[['办理方式',type],['费用／审批',offerCost(s,o)],['实际库存',C.count(o.库存)?num(o.库存):'待问询'],['身份权限',allowed?'符合已知身份与层级，仍须核验实际条件':'当前权限或条件尚未满足']])+(!allowed?'':('<div class="wf-form"><label>数量<input type="number" min="1" max="99" data-field="qty" value="'+E(ui.qty??1)+'" aria-invalid="'+!qtyOK+'" aria-describedby="wf-qty-help"></label><p id="wf-qty-help" class="'+(qtyOK?'wf-form-help':'wf-field-message')+'">'+(qtyOK?'器物与功法逐项办理。':'数量须为1至99的整数。')+'</p>'+(type==='借阅'?'<label>借阅日数<input type="number" min="1" max="366" data-field="days" value="'+E(ui.days??1)+'" aria-invalid="'+!daysOK+'" aria-describedby="wf-days-help"></label><p id="wf-days-help" class="'+(daysOK?'wf-form-help':'wf-field-message')+'">'+(daysOK?'按此卷实际获准期限核对。':'借阅日数须为1至366的整数。')+'</p>':'')+'</div><div class="wf-summary-total" data-feedback-zone="price"><span>本次预计费用</span><strong>'+E(total)+'</strong></div>'+(warning?'<p class="wf-local-feedback" data-wf-key="offer-condition">'+E(warning)+'，可先问询条件；不自动扣费或发货。</p>':'')))+'<div class="dialog-actions">'+(allowed?button('递交'+(type||'办理')+'申请','apply',{type,id},true):'')+button('先问询条件','ask',{text:'我想了解「'+o.名称+'」的实际提供条件、价格、库存及对应审批，不直接获得或学会。'})+'</div><p class="dialog-note">申请仅登记待办并拟写行动，发送后核验；审批与实际交付分别确认。</p>';}
  function tournament(s){const t=C.tournament(s);if(!t)return '<p>当前实际修为没有对应的弟子大比赛区。器灵根初入凡人须先实际引气入道；合体及以上按高阶论法安排。</p>';const r=t.场次;return '<section class="panel"><div class="small-label">'+E(t.赛场)+' · 按实际修为分组</div><h3>'+E(t.境界)+'组 · '+E(t.周期)+'</h3><p>场次：'+E(r?.标题||'待核对本届公告')+'</p><p>开赛：'+E(r?.开始||'待排期')+'</p><p>报名：'+E(r?.报名||'未确认')+' · '+E(t.剩余日数===null?'距开赛时间待核对':t.剩余日数===0?'已到公告开赛时间，请核对进度':'距开赛约 '+t.剩余日数+' 日')+'</p><div class="study-actions">'+button('查看大比','tournament-action',{kind:'查看大比'})+button('报名备赛','tournament-action',{kind:'报名备赛'})+(t.可继续?button('继续本届大比','tournament-action',{kind:'继续本届大比'},true):button('备赛至开赛','tournament-action',{kind:'备赛至开赛'},true,!t.可推进))+'</div></section><p class="dialog-note">先确认本届报名与开赛日期，再安排备赛至开赛。行动填入输入框，由你发送；推进前核对紧急事务和已有约定，停在赛前准备阶段。</p><table class="ledger"><thead><tr><th>境界组</th><th>周期</th></tr></thead><tbody><tr><td>炼气</td><td>每季度</td></tr><tr><td>筑基</td><td>每半年</td></tr><tr><td>金丹</td><td>每年</td></tr><tr><td>元婴</td><td>每两年</td></tr><tr><td>化神、炼虚分别设组</td><td>每三年</td></tr></tbody></table>';}
  function practice(s){return '<section class="wf-practice" data-wf-key="practice"><div class="study-actions">'+button('继续修炼','practice-action',{kind:'继续修炼'},true)+button('请教师尊','practice-action',{kind:'请教师尊'})+'</div><details class="wf-more" data-wf-key="more-practice"><summary>其他修行 '+icon('down')+'</summary><div class="study-actions">'+['调养恢复','服丹与突破准备','核对近期安排'].map(kind=>button(kind,'practice-action',{kind})).join('')+'</div></details><p>先核对条件与耗时，再由你发送行动。</p></section>';}
  function workshopOffer(s,id,ui){const f=C.extension(s).工坊?.[id];if(!f)return '<p>工坊记录已变化。</p>';let fee;const months=Number(ui.months??1),valid=Number.isInteger(months)&&months>=1&&months<=120;try{fee=C.workshopPrice(s,f,months);}catch(error){fee={有效:false,说明:error.message};}return '<p>'+br(f.说明)+'</p>'+group('场地条件',[['当前待遇',fee.说明],['专项费用','材料、代工与专项设备分别核价。'],['实际开工','排期与场地获准不等于已经生产。']])+'<div class="wf-form"><label>月数<input type="number" min="1" max="120" data-field="months" value="'+E(ui.months??1)+'" aria-invalid="'+!valid+'" aria-describedby="wf-months-help"></label><p id="wf-months-help" class="'+(valid?'wf-form-help':'wf-field-message')+'">'+(valid?'实际租期与设备依剧情确认。':'月数须为1至120的整数。')+'</p></div><div class="wf-summary-total" data-feedback-zone="price"><span>本次场租</span><strong>'+E(fee.有效?num(fee.总价)+' 贡献':'待核对')+'</strong></div><p class="dialog-note">'+E(fee.有效?'免 '+fee.免租月数+' 个月；配额只在成功办理后扣减。':'请先核对报价和配额。')+'</p><div class="dialog-actions">'+button('递交租借申请','rent',{id},true,!fee.有效||!valid)+button('先问询排期','ask',{text:'我想核对「'+f.名称+'」的设备、排期、场租与免租剩余月数；专项费用与材料费分别列明。'})+'</div>';}
  function settings(settings,ui,health){const f=ui.settingsDraft||settings;return '<p>沿用原卡共享MVU。选择一种万法宗记录更新通道，原卡自身的更新方式保持原设。</p><div class="wf-form"><label>更新通道<select data-field="mode">'+[['body','正文'],['extra','原卡额外解析'],['api','独立API']].map(([v,l])=>'<option value="'+v+'" '+(f.mode===v?'selected':'')+'>'+l+'</option>').join('')+'</select></label>'+(f.mode==='api'?'<label class="wide">API地址<input data-field="url" value="'+E(f.url)+'" autocomplete="off" placeholder="https://…"></label><label>模型<input data-field="model" value="'+E(f.model)+'" autocomplete="off"></label><label>密钥<input type="password" data-field="key" value="'+E(f.key)+'" autocomplete="off"></label><label>最大输出<input type="number" data-field="tokens" value="'+E(f.tokens)+'" min="256" max="16000"></label><label><input type="checkbox" data-field="automatic" '+(f.automatic?'checked':'')+'>新回复后更新</label>':'')+'</div><p class="dialog-note">配置保存在本机酒馆设置，不写入聊天变量或导出脚本。更新状态：'+E(health.update?.state||'空闲')+'</p><div class="dialog-actions">'+button('保存设置','save-settings',{},true)+button('核对当前回复','update-now')+'</div>';}
  function modal(ui){if(ui.city)return '<dialog class="city-dialog" id="wf-dialog"><div class="city-dialog-head"><div><span class="eyebrow">云上万法 · 一城百艺</span><h2>万法天仪</h2></div><div class="city-controls">'+button(ui.zoom?'适应画面':'放大细看','zoom')+'<button class="icon-btn" data-action="close-dialog" aria-label="关闭全景">'+icon('close')+'</button></div></div><div class="city-image-scroll '+(ui.zoom?'zoomed':'')+'"><img src="'+assets.image+'" alt="万法天仪仙城概念全景"></div><p class="city-caption">中央神州东南天穹 · 仙城概念图。查看不改变剧情地点。</p></dialog>';if(!ui.modal)return '<dialog id="wf-dialog" class="detail-dialog"></dialog>';return '<dialog class="detail-dialog '+(ui.modal.wide?'wf-wide':'')+'" id="wf-dialog"><header class="dialog-header"><div><span class="eyebrow">'+E(ui.modal.kicker)+'</span><h2>'+E(ui.modal.title)+'</h2></div><button class="icon-btn" data-action="close-dialog" aria-label="关闭">'+icon('close')+'</button></header><div class="dialog-body">'+ui.modal.body+'</div></dialog>';}
  function render(s,ui,settings,health){const p=C.obj(s.主角),navs=[['identity','宗籍','seal'],['teaching','传道','lamp'],['library','藏经','book'],['workshop','百工','work'],['merit','功德','scroll'],['city','仙城','city']];return '<style>'+assets.css+'</style><main class="device"><header class="masthead"><div class="brand"><div class="brand-mark">'+icon('seal')+'</div><div><h1>万法宗</h1><p>有教无类 · 以术证道</p></div></div><div class="head-right"><div class="world-time"><span>'+E(p.姓名||'名籍待核对')+' · '+E(C.role(s)||'身份待核对')+'</span><small>'+E(s.世界?.当前时间||'剧情时间待核对')+'</small></div><button class="icon-btn" data-action="calendar" aria-label="修行岁序">'+icon('calendar')+'</button><button type="button" class="icon-btn wf-theme" data-action="theme" aria-pressed="'+(ui.theme==='xuanqing')+'" aria-label="'+(ui.theme==='xuanqing'?'当前玄青主题，切换为原木':'当前原木主题，切换为玄青')+'" title="'+(ui.theme==='xuanqing'?'切换为原木':'切换为玄青')+'">'+icon(ui.theme==='xuanqing'?'moon':'sun')+'</button><button class="icon-btn wf-settings" data-action="settings" aria-label="更新设置">'+icon('setting')+'</button><button class="icon-btn" data-action="collapse" aria-expanded="'+ui.open+'" aria-label="'+(ui.open?'收起机关令':'展开机关令')+'">'+icon(ui.open?'collapse':'expand')+'</button></div></header>'+(ui.open?'<nav class="nav" aria-label="机关令功能">'+navs.map(([id,label,n])=>'<button data-action="page" data-page="'+id+'" class="'+(id===ui.page?'active':'')+'" aria-current="'+(id===ui.page?'page':'false')+'">'+icon(n)+label+'</button>').join('')+'</nav><div class="page">'+({identity:()=>home(s),teaching:()=>teaching(s),library:()=>library(s,ui),workshop:()=>workshop(s),merit:()=>merit(s,ui),city:()=>city(s)})[ui.page]()+'</div>':'')+(ui.intent&&!ui.intent.sent?'<div class="wf-feedback wf-draft-strip" role="status"><span>已拟写行动，等待发送。<small>先核对条件，再由你发送；未确认不扣发。</small></span> '+button('撤回本次草稿','withdraw-draft')+'</div>':'')+'<footer class="footer"><span class="footer-mark">万法机关令</span><span>一城百艺 · 各有所长</span><span>'+E(health.update?.state==='请求中'?'正在核对记录':'以当前剧情为准')+'</span></footer></main>'+modal(ui);}
  return {E,br,icon,button,link,empty,value,facts,group,render,profile,record,offer,calendar,tournament,practice,workshopOffer,settings,offerType,offerCost,bookRows,reward};
}

function createWanfaContext(C,rules){
  'use strict';
  const cfg=rules.context,strip=v=>String(v||'').replace(/<UpdateVariable\b[^>]*>[\s\S]*?<\/UpdateVariable>/gi,''),short=(v,n=100)=>C.str(v,n),active=t=>['待确认接取','进行中','待结算'].includes(t.状态),pending=r=>['待确认','已批准','待核价'].includes(r.状态);
  const fieldTopic={任务:'task',办理:'trade',目录:'trade',借阅:'library',工坊:'workshop',研造:'workshop',课业:'teaching',日程:'calendar',活动:'calendar',入门:'intro',名籍:'intro',后天灵根:'roots',研习:'cultivation'};
  const inSect=s=>String(s?.世界?.当前地点||'').includes('万法');
  function rootState(s){const x=C.extension(s),r=C.obj(x.后天灵根),label=String(s?.主角?.灵根||'');const obtained=/器灵根|丹灵根/.test(label)||(/成功|已完成/.test(String(r.施术状态))&&/器灵根|丹灵根/.test(String(r.类型))),signed=/已签|有效/.test(String(r.契约?.状态));return {needed:obtained||signed,record:r,kind:obtained?(/器灵根/.test(label+' '+r.类型)?'器灵根':'丹灵根'):'契约已签，施术按实际阶段'};}
  function choose(rows,text,id,limit=1){const selected=[],seen=new Set(),push=row=>{if(row&&!seen.has(row[0])){seen.add(row[0]);selected.push(row);}};push(rows.find(([k])=>k===id));for(const row of rows){const name=String(row[1].名称||row[1].标题||'');if(name.length>=2&&text.includes(name))push(row);}for(const row of rows)push(row);return selected.slice(0,limit);}
  function plan(s,options={}){
    const x=C.extension(s),messages=options.messages||[],lastUser=[...messages].reverse().find(m=>m.role==='user'&&!m.is_hidden),user=strip(options.user??lastUser?.message),story=options.phase==='update'?strip(options.story||[...messages].reverse().find(m=>m.role==='assistant'&&!m.is_hidden)?.message):'',text=user+'\n'+story,intent=options.intent||null,details=intent?.details||intent||{},topics=new Set(),role=C.role(s),member=C.member(s),local=inSect(s),phase=String(x.入门?.阶段||''),reception=String(s.世界?.当前地点||'').includes('接引登记殿'),fullEntry=reception&&(!member||cfg.entryPhase.includes(phase));
    const add=k=>topics.add(k);
    const entryQuestion=/(?:想|申请|询问|问询|请问|如何|能否|打算).{0,12}(?:加入万法宗|拜入万法宗|万法宗入门|万法宗招生)|(?:加入万法宗|万法宗入门).{0,6}(?:条件|手续|要求)|(?:恢复|补齐|核对|继续).{0,6}(?:登记|入门手续)|测灵根/.test(user);
    if(entryQuestion||/万法(?:入门|拜师|收徒|测灵)/.test(user)||/(?:核对|恢复|补齐).{0,20}(?:名籍|身份|师承|居所|入门时间|登记漏项)/.test(user)||user.trim()==='加入万法宗'||fullEntry||!member&&cfg.entryPhase.includes(phase)||options.phase==='update'&&/接引登记殿|测灵核验|登记授令|入门登记/.test(story))add('intro');
    if(/宗门任务|接取|交付|交差|回报|验收|任务进度|任务报酬|凡级|黄级|玄级|地级|天级/.test(text))add('task');
    if(/丹药|筑基丹|凝金丹|化婴丹|相生神游丹|虚合破元丹|天罡合体丹|虚灵丹|申领|配给|资源审批|物资目录|兑换|领取物资|办理记录/.test(text))add('trade');
    if(/藏经阁|借阅|拓印|归还|传承申请|典籍目录|阅览权限/.test(text))add('library');
    if(/工坊|研造|机关造物|场租|租借|免租|机件|试制|灵材|丹房|阵胚/.test(text))add('workshop');
    if(/讲席|课业|听讲|赴课|请教|讲师|师承答疑/.test(text))add('teaching');
    if(/月俸|俸禄|岁序|日程|会期|课程安排|记事|日期安排|结缘大会|百宝集|冲榜赛|星轨参天/.test(text))add('calendar');
    if(/大比|报名备赛|备赛至开赛|本届比赛/.test(text))add('tournament');
    if(/修炼|调养|疗伤|恢复灵力|服丹|突破准备|研习|参悟|练习|功法|推演/.test(text))add('cultivation');
    if(/器灵根|丹灵根|后天灵根|造根|本命器物受损|本命法器受损|生死契约/.test(text))add('roots');
    const kind=String(details.类型||''),operation=String(details.操作||'');
    if(kind==='接取任务')add('task');
    if(kind==='门内大比')add('tournament');
    if(kind==='记事')add('calendar');
    if(kind==='个人修行'){add(operation==='请教师尊'?'teaching':'cultivation');if(operation==='服丹与突破准备')add('trade');if(operation==='核对近期安排'){add('task');add('teaching');add('workshop');}}
    if(kind==='界面办理'){const receipt=x.办理?.[details.编号],type=receipt?._凭证?.类型;add(type==='工坊租借'?'workshop':['借阅','归还','拓印','传承'].includes(type)?'library':'trade');}
    if(kind==='问询'&&intent){for(const field of ['任务','课业','研习','目录','借阅','工坊','研造','日程','活动'])for(const [,r]of C.collection(x,field)){const name=String(r.名称||r.标题||'');if(name.length>=2&&user.includes(name))add(field==='目录'?['借阅','拓印','传承'].includes(r.方式)?'library':'trade':fieldTopic[field]);}}
    const paths=options.paths||[];for(const p of paths){const f=String(p).split('/')[2];if(fieldTopic[f])add(fieldTopic[f]);}
    for(const field of ['研造','研习','课业','日程','活动'])for(const [,r]of C.collection(x,field)){const name=String(r.名称||r.标题||'');if(name.length>=2&&text.includes(name))add(fieldTopic[field]);}
    const matchedTasks=C.collection(x,'任务').filter(([,t])=>active(t)||t.名称?.length>=2&&text.includes(t.名称));for(const [,t]of matchedTasks)if(t.名称?.length>=2&&text.includes(t.名称))add('task');
    const matchedReceipts=C.collection(x,'办理').filter(([,r])=>pending(r));for(const [,r]of matchedReceipts)if(r._凭证?.名称?.length>=2&&text.includes(r._凭证.名称))add(r._凭证.类型==='工坊租借'?'workshop':['借阅','归还','拓印','传承'].includes(r._凭证.类型)?'library':'trade');
    if(!local&&/客栈|当地|此地|外界|别宗|其他宗门|散修.{0,6}(?:雇佣|悬赏)|药铺/.test(text)&&!/万法|本宗|功德堂/.test(text)&&!intent&&paths.length===0){const ownTask=matchedTasks.some(([,t])=>t.名称?.length>=2&&text.includes(t.名称)),ownReceipt=matchedReceipts.some(([,r])=>r._凭证?.名称?.length>=2&&text.includes(r._凭证.名称));for(const t of [...topics])if(!['intro','cultivation','roots'].includes(t)&&!(t==='task'&&ownTask)&&!ownReceipt)topics.delete(t);}
    if(kind==='个人修行'&&operation==='服丹与突破准备'&&!/申领|兑换|申请配给/.test(user))topics.delete('trade');
    // 既有宗籍、日期未知或页面停留，不会自行重新加载整套入门流程。
    const allowed=member||C.updateAllowed(s);if(!allowed)topics.clear();
    if(!member)for(const t of [...topics])if(!['intro','roots'].includes(t))topics.delete(t);
    const ordered=Object.keys(cfg.topics).filter(k=>topics.has(k)),markers=ordered.map(k=>'⟦万法专题:'+cfg.topics[k]+'⟧');
    if(topics.has('workshop'))markers.push('⟦万法设施:'+(/阵法|阵胚|阵盘/.test(text)?'阵法':/丹|火|炉/.test(text)?'丹器':'机关')+'⟧');
    const tasks=member?choose(matchedTasks,text,details.类型==='接取任务'?details.编号:x.追踪任务,topics.has('task')?3:1):[],receipts=member?choose(matchedReceipts,text,details.类型==='界面办理'?details.编号:'',topics.has('trade')||topics.has('workshop')||topics.has('library')?2:tasks.length?0:1):[];
    const state={世界:{当前时间:s.世界?.当前时间,当前地点:s.世界?.当前地点},主角:{宗门:s.主角?.宗门,境界:s.主角?.境界,宗门贡献:s.主角?.宗门贡献},万法宗:{}};
    const put=(field,rows)=>{if(rows.length)state.万法宗[field]=Object.fromEntries(rows);};
    if(topics.has('intro')){state.万法宗.名籍=x.名籍;state.万法宗.入门=x.入门;}
    if(topics.has('task'))put('任务',tasks);
    if(receipts.length)put('办理',receipts);
    if(topics.has('trade')||topics.has('library'))put('目录',choose(C.collection(x,'目录'),text,'',3));
    if(topics.has('library'))put('借阅',choose(C.collection(x,'借阅').filter(([,b])=>b.状态==='借阅中'),text,'',2));
    if(topics.has('workshop')){put('工坊',choose(C.collection(x,'工坊'),text,'',2));put('研造',choose(C.collection(x,'研造').filter(([,r])=>!['已完成','已归档'].includes(r.状态)),text,'',2));}
    if(topics.has('teaching'))put('课业',choose(C.collection(x,'课业'),text,'',3));
    if(topics.has('calendar')){put('日程',choose(C.collection(x,'日程').filter(([,e])=>!['已完成','已取消'].includes(e.状态)),text,'',3));put('成果',C.collection(x,'成果').filter(([id,e])=>/月俸|俸禄/.test(id+' '+e.来源+' '+e.名称)).slice(-2));}
    if(topics.has('tournament')){const t=C.tournament(s);if(t?.场次){const a=t.场次;put(a.来源,[[a.编号,x[a.来源]?.[a.编号]]]);}}
    if(topics.has('cultivation'))put('研习',choose(C.collection(x,'研习').filter(([,r])=>!['已完成','已归档'].includes(r.状态)),text,'',2));
    const roots=rootState(s);if(roots.needed||topics.has('roots')){state.万法宗.后天灵根=roots.record;const name=roots.record.本命器物名称;if(name&&s.主角?.器物?.[name])state.主角.器物={[name]:s.主角.器物[name]};}
    const rows=['【万法随身】'+(member?role+'；'+short(s.主角?.境界,40)+'；贡献'+s.主角?.宗门贡献:'入门按实际阶段')];
    if(x.名籍?.师承)rows.push('师承：'+short(x.名籍.师承,30));
    for(const [id,t]of tasks)rows.push('任务 '+id+'：'+short(t.名称,26)+'｜'+t.状态+'｜'+short(t.目标,60)+(t.截止时间?'｜期限'+short(t.截止时间,38):''));
    for(const [id,r]of receipts)rows.push('办理 '+id+'：'+short(r._凭证?.名称,30)+'｜'+r.状态+'｜'+r._凭证?.总价+'贡献；所得尚依实际结果');
    if(roots.needed){const r=roots.record,name=r.本命器物名称;rows.push('后天记录：'+roots.kind+(r.修炼等效档位?'；等效'+r.修炼等效档位:'')+(name?'；本命'+short(name,40)+'；'+(short(s.主角?.器物?.[name]?.状态,30)||'状态待核对')+'；损耗'+(s.主角?.器物?.[name]?.损耗度??'待核对'):'')+(r.契约?.状态?'；契约'+short(r.契约.状态,20):''));}
    if(topics.has('intro'))rows.push('办理：'+(phase||'问询未登记')+'；'+(x.名籍?.入门时间?'已有真实入门记录':'未知记录先核对'));
    if(topics.has('tournament')){const t=C.tournament(s);rows.push('大比：'+(t?t.境界+'组，'+t.周期+'；'+(t.场次?JSON.stringify(t.场次):'待排期'):'无对应弟子赛区'));}
    // 只有本次相关数据才随话题携带；本地页面与全量档案不受裁剪影响。
    const detailFields={task:'任务',trade:'目录',library:'借阅',workshop:'工坊',teaching:'课业',calendar:'日程',cultivation:'研习'};
    for(const topic of ordered){const field=detailFields[topic];if(field&&state.万法宗[field]){const clean=Object.fromEntries(Object.entries(state.万法宗[field]).map(([id,r])=>[id,Object.fromEntries(Object.entries(r).filter(([k])=>!k.startsWith('_')))]));rows.push(field+'：'+JSON.stringify(clean));}}
    if(topics.has('calendar')&&state.万法宗.成果)rows.push('月俸已领记录：'+JSON.stringify(state.万法宗.成果));
    if(receipts.length)rows.push('待办凭据：'+JSON.stringify(Object.fromEntries(receipts.map(([id,r])=>[id,{类型:r._凭证?.类型,名称:r._凭证?.名称,数量:r._凭证?.数量,总价:r._凭证?.总价,政策:r._凭证?.政策}]))));
    if(intent)rows.push('本次界面行动：'+JSON.stringify(Object.fromEntries(Object.entries(details).filter(([k])=>['类型','操作','编号','场次','来源','开始','报名'].includes(k)))));
    const summary=rows.join('\n'),protocol=cfg.base,topicText=ordered.map(k=>cfg.text[k]).join('\n')+(fullEntry?'\n'+rules.entry:''),apiText=(member&&!local?cfg.text.carry+'\n':'')+(roots.needed?cfg.text.effects+'\n':'')+topicText;
    return {topics:ordered,markers:[...new Set(markers)],summary,protocol,apiRules:protocol+'\n'+apiText,apiState:state,fullEntry,local,characters:summary.length+protocol.length,topicCharacters:topicText.length,needsUpdate:ordered.length>0};
  }
  return {plan,inSect,rootState};
}

function createWanfaUIState(host,doc){
  'use strict';
  const key=node=>{
    if(node.nodeType!==1)return '#'+node.nodeType;
    if(node.id)return node.tagName+'#'+node.id;
    if(node.dataset.wfKey)return node.tagName+'|key|'+node.dataset.wfKey;
    if(node.dataset.field)return node.tagName+'|field|'+node.dataset.field;
    if(node.dataset.action)return node.tagName+'|action|'+JSON.stringify(node.dataset);
    return node.tagName+'|'+node.className;
  };
  const locator=node=>node?.nodeType===1?{id:node.id,field:node.dataset.field,action:node.dataset.action,data:{...node.dataset}}:null;
  function find(root,ref){
    if(!root||!ref)return null;
    if(ref.id)return [...root.querySelectorAll('[id]')].find(e=>e.id===ref.id)||null;
    if(ref.field)return [...root.querySelectorAll('[data-field]')].find(e=>e.dataset.field===ref.field)||null;
    if(ref.action)return [...root.querySelectorAll('[data-action]')].find(e=>Object.entries(ref.data).every(([k,v])=>e.dataset[k]===v))||null;
    return null;
  }
  function update(old,fresh){
    if(old.nodeType!==1){if(old.nodeValue!==fresh.nodeValue)old.nodeValue=fresh.nodeValue;return;}
    for(const a of [...old.attributes])if(!fresh.hasAttribute(a.name)&&!(['DIALOG','DETAILS'].includes(old.tagName)&&a.name==='open'))old.removeAttribute(a.name);
    for(const a of fresh.attributes)if(old.getAttribute(a.name)!==a.value)old.setAttribute(a.name,a.value);
    if(old.tagName==='TEXTAREA'){
      if(old.value!==fresh.value)old.value=fresh.value;old.defaultValue=fresh.defaultValue;return;
    }
    children(old,fresh);
    if(old.tagName==='INPUT'){if(old.value!==fresh.value)old.value=fresh.value;old.checked=fresh.checked;}
    if(old.tagName==='SELECT'&&old.value!==fresh.value)old.value=fresh.value;
  }
  function children(parent,fresh){
    let cursor=parent.firstChild;
    for(const incoming of [...fresh.childNodes]){
      let node=cursor;
      if(!node||key(node)!==key(incoming)){
        node=null;for(let test=cursor;test;test=test.nextSibling)if(key(test)===key(incoming)){node=test;break;}
        if(node)parent.insertBefore(node,cursor);else{node=incoming.cloneNode(true);parent.insertBefore(node,cursor);}
      }
      update(node,incoming);cursor=node.nextSibling;
    }
    while(cursor){const next=cursor.nextSibling;cursor.remove();cursor=next;}
  }
  function capture(shadow,mount){
    const active=shadow.activeElement,selection=active&&['INPUT','TEXTAREA'].includes(active.tagName)?{start:active.selectionStart,end:active.selectionEnd,direction:active.selectionDirection}:null;
    const scroll=[];for(let e=mount;e;e=e.parentElement)if(e.scrollHeight>e.clientHeight||e.scrollWidth>e.clientWidth)scroll.push({node:e,top:e.scrollTop,left:e.scrollLeft});
    for(const e of shadow.querySelectorAll('#wf-dialog,.dialog-body,.city-image-scroll'))scroll.push({node:e,ref:locator(e),class:e.className,top:e.scrollTop,left:e.scrollLeft});
    const rect=active?.getBoundingClientRect(),anchor=rect&&rect.height>0&&rect.bottom>0&&rect.top<host.innerHeight?rect.top:null;
    return {active,ref:locator(active),selection,scroll,anchor,x:host.scrollX,y:host.scrollY};
  }
  function restore(shadow,saved,focus=true){
    if(focus&&saved.active){const node=saved.active.isConnected?saved.active:find(shadow,saved.ref);if(node&&node.getClientRects().length){node.focus({preventScroll:true});if(saved.selection&&saved.selection.start!==null)try{node.setSelectionRange(saved.selection.start,saved.selection.end,saved.selection.direction);}catch{}}}
    for(const item of saved.scroll){const e=item.node.isConnected?item.node:find(shadow,item.ref)||[...shadow.querySelectorAll('.dialog-body,.city-image-scroll')].find(n=>n.className===item.class);if(e){e.scrollTop=item.top;e.scrollLeft=item.left;}}
    if(host.scrollX!==saved.x||host.scrollY!==saved.y)host.scrollTo(saved.x,saved.y);
    if(focus&&saved.anchor!==null&&saved.active?.isConnected&&saved.active.getClientRects().length){
      const delta=saved.active.getBoundingClientRect().top-saved.anchor;
      if(Math.abs(delta)>1){const parent=saved.active.closest('.dialog-body,.city-image-scroll')||saved.scroll.find(i=>!i.node.getRootNode().host)?.node;if(parent)parent.scrollTop+=delta;}
    }
  }
  function patch(shadow,html){const template=doc.createElement('template');template.innerHTML=html;children(shadow,template.content);}
  return {capture,restore,patch,locator,find};
}

